commands.command:
set -eu
ROOT="$HOME/agent-workspace/repos/photomap/work"
cd "$ROOT"
test "$(git branch --show-current)" = main
test "$(git rev-parse HEAD)" = 356289656d66963fb7451b70eac2e1bcff015819
test -z "$(git status --porcelain)"
node <<'NODE'
const {chromium}=require('./frontend/node_modules/@playwright/test');
(async()=>{
 const browser=await chromium.launch({headless:true,executablePath:'/Applications/Google Chrome.app/Contents/MacOS/Google Chrome'});
 const page=await browser.newPage({viewport:{width:390,height:844}});
 let errors=[];page.on('pageerror',e=>errors.push(e.message));
 const response=await page.goto('https://photomap.pl/',{waitUntil:'domcontentloaded',timeout:35000});
 await page.locator('.pinned-media-drawer').waitFor({timeout:25000});
 const state=await page.evaluate(()=>({
   stage:document.querySelector('.pinned-media-drawer')?.getAttribute('data-stage'),
   legacyMenu:!!document.querySelector('.shell-menu-button'),
   legacyRailPresent:!!document.querySelector('.side-rail'),
   newMapToolsPresent:!!document.querySelector('.map-tools')
 }));
 console.log("LIVE_OLD_UI_STATE="+JSON.stringify({http:response.status(),...state,errors}));
 await browser.close();
 if(response.status()!==200 || state.stage!=='collection' || state.newMapToolsPresent || errors.length)process.exit(2);
})().catch(e=>{console.error(e);process.exit(1)});
NODE
echo LIVE_OLD_UX_BROWSER_PASS
